def solve(data):
    if data['booking_state'] != 'cancelled':
        return 0
    charges = sum(row['cents'] for row in data['charges'] if row['state'] == 'posted')
    concessions = sum(row['cents'] for row in data['concessions'] if row['state'] == 'posted')
    hours = data['hours_notice']
    allowance = charges if hours >= 48 else charges // 2 if hours >= 24 else 0
    return max(0, min(data['cap_cents'], allowance) - concessions)

def solve(data):
    result = []
    previous = None
    for run in data['runs']:
        if run['state'] == 'deleted':
            previous = None
            continue
        color = run['color']
        if color == previous:
            result[-1]['pixels'] += run['pixels']
        else:
            result.append({'color': color, 'pixels': run['pixels']})
        previous = color
    return result

import unicodedata


def solve(data):
    seen = set()
    kept = []
    for name in data['names']:
        key = unicodedata.normalize('NFKC', name)
        if key not in seen:
            seen.add(key)
            kept.append(name)
    return kept
